if (n == 0) return 1.0;
const double abs_alpha_sq = std::norm(alpha);
if (abs_alpha_sq < 100.0) {
    dcomp result = 1.0;
    double norm_factor = 1.0;
    for (unsigned long k = 1; k <= n; ++k) {
        result *= alpha;
        norm_factor *= k;
        result /= std::sqrt(static_cast<double>(k));
    }
    return result * std::exp(-0.5 * abs_alpha_sq);
} else {
    // Stirling approximation for large n
    const double ln_n_fact = n * std::log(static_cast<double>(n)) - static_cast<double>(n) + 0.5 * std::log(2.0 * M_PI * static_cast<double>(n));
    const double ln_alpha_n = n * std::log(std::abs(alpha));
    const double ln_coeff = ln_alpha_n - 0.5 * ln_n_fact - 0.5 * abs_alpha_sq;
    const double magnitude = std::exp(ln_coeff);
    const double phase = std::arg(alpha) * static_cast<double>(n);
    return magnitude * std::polar(1.0, phase);
}

